303:       draws.push({ depth: x + y + .3, draw: () => this.drawStaff(id, x, y, st, crew) });
304:     }
305:     // customers
306:     for (const c of this.game.runtime.customers) {
307:       draws.push({ depth: c.x + c.y + .45, draw: () => this.drawCustomer(c) });
308:     }
309:     // ambient cat
310:     if (p.id === 'apartment') {
311:       const cat = this.updateCat(dt);
312:       draws.push({ depth: cat[0] + cat[1] + .4, draw: () => this.drawCat(cat[0], cat[1]) });
313:     }
314:     draws.sort((a, b) => a.depth - b.depth);
315:     for (const d of draws) d.draw();
316:     this.drawWorldParticles(dt);
317:     this.drawLighting(p);
318:     this.screenTransform();
319:     this.drawBubbles();
320:     this.drawHover();
321:     this.drawScreenFx(dt);
322:     this.shake = Math.max(0, this.shake - dt * 2.2);
323:     this.flash = Math.max(0, this.flash - dt * 1.4);
324:   }
