326:   updateCat(dt) {
327:     const a = this.ambient;
328:     a.catTimer -= dt;
329:     if (a.catTimer <= 0) {
330:       a.catTarget = [1.2 + Math.random() * 6, 3.2 + Math.random() * 2.8];
331:       a.catTimer = 3 + Math.random() * 5;
332:     }
333:     const dx = a.catTarget[0] - a.catX, dy = a.catTarget[1] - a.catY;
334:     const d = Math.hypot(dx, dy);
335:     if (d > .08) { a.catX += dx / d * .45 * dt; a.catY += dy / d * .45 * dt; }
336:     return [a.catX, a.catY];
337:   }
