339:   // ---------- backdrop ----------
340:   drawBackdrop() {
341:     const ctx = this.ctx, w = this.w, h = this.h;
342:     const hour = this.game.hour;
343:     const night = (hour < 6.4 || hour > 19.2) ? 1 : (hour < 8 ? (8 - hour) / 1.6 : hour > 17.5 ? (hour - 17.5) / 1.7 : 0);
344:     const nf = clamp(night, 0, 1);
345:     const g = ctx.createLinearGradient(0, 0, 0, h);
346:     if (nf > .5) {
347:       g.addColorStop(0, '#080d13'); g.addColorStop(.55, '#0b1418'); g.addColorStop(1, '#121b1a');
348:     } else {
349:       g.addColorStop(0, '#0d1a1b'); g.addColorStop(.45, '#12251f'); g.addColorStop(1, '#1b241c');
350:     }
351:     ctx.fillStyle = g; ctx.fillRect(0, 0, w, h);
352: 
353:     // horizon glow
354:     const hg = ctx.createRadialGradient(w * .5, h * .55, 10, w * .5, h * .55, w * .72);
355:     hg.addColorStop(0, nf > .5 ? 'rgba(80,160,150,.09)' : 'rgba(230,190,110,.14)');
356:     hg.addColorStop(.5, 'rgba(70,120,90,.05)');
357:     hg.addColorStop(1, 'rgba(0,0,0,0)');
358:     ctx.fillStyle = hg; ctx.fillRect(0, 0, w, h);
359: 
360:     // stars
361:     if (nf > .25) {
362:       for (let i = 0; i < 70; i++) {
363:         const x = seeded(i * 2.7) * w, y = seeded(i * 8.3) * h * .52;
364:         const a = (0.25 + seeded(i * 4.1) * .6) * nf;
365:         ctx.fillStyle = `rgba(210,240,235,${a})`;
366:         const s = seeded(i * 5.9) > .85 ? 1.6 : .8;
367:         ctx.fillRect(x, y, s, s);
368:       }
369:       // moon
370:       const mx = w * .83, my = h * .16;
371:       const mg = ctx.createRadialGradient(mx, my, 2, mx, my, 52);
372:       mg.addColorStop(0, 'rgba(240,245,220,.95)'); mg.addColorStop(.35, 'rgba(220,235,210,.18)'); mg.addColorStop(1, 'rgba(200,230,220,0)');
373:       ctx.fillStyle = mg; ctx.beginPath(); ctx.arc(mx, my, 52, 0, TAU); ctx.fill();
374:       ctx.fillStyle = 'rgba(238,244,216,.9)'; ctx.beginPath(); ctx.arc(mx, my, 13, 0, TAU); ctx.fill();
375:     }
376: 
377:     // city silhouette
378:     ctx.save();
379:     for (const layer of [0, 1]) {
380:       const base = h * (layer ? .60 : .56);
381:       for (const b of this.city) {
382:         if (b.layer !== layer) continue;
383:         const bh = b.h * h * (layer ? 1 : .8), bw = b.w * w;
384:         const x = b.x * w, y = base - bh;
385:         ctx.fillStyle = layer ? 'rgba(8,18,17,.45)' : 'rgba(7,14,14,.7)';
386:         ctx.fillRect(x, y, bw, bh);
387:         if (b.antenna) ctx.fillRect(x + bw / 2, y - 10, 1.5, 10);
388:         if (nf > .35 && layer === 1) {
389:           ctx.fillStyle = `rgba(255,205,110,${.08 + .1 * b.lit})`;
390:           for (let wy = y + 6; wy < base - 4; wy += 7) {
391:             for (let wx = x + 3; wx < x + bw - 3; wx += 6) {
392:               if (seeded(wx * .7 + wy * 1.3 + b.x) > .55) ctx.fillRect(wx, wy, 1.5, 2);
393:             }
394:           }
395:         }
396:       }
397:     }
398:     ctx.restore();
399: 
400:     // fog bands
401:     for (let i = 0; i < 3; i++) {
402:       const fy = h * (.52 + i * .05) + Math.sin(this.time * .06 + i) * 6;
403:       const fg = ctx.createLinearGradient(0, fy - 24, 0, fy + 34);
404:       fg.addColorStop(0, 'rgba(70,110,100,0)'); fg.addColorStop(.5, `rgba(80,130,115,${.045 - i * .01})`); fg.addColorStop(1, 'rgba(70,110,100,0)');
405:       ctx.fillStyle = fg; ctx.fillRect(0, fy - 24, w, 58);
406:     }
407: 
408:     // dust motes
409:     ctx.save();
410:     for (let i = 0; i < 22; i++) {
411:       const x = (seeded(i * 3.7) * w + this.time * (3 + seeded(i) * 6)) % w;
412:       const y = (seeded(i * 8.1) * h + Math.sin(this.time * .3 + i) * 20) % h;
413:       ctx.fillStyle = `rgba(190,225,190,${.03 + seeded(i * 9.3) * .06})`;
414:       ctx.beginPath(); ctx.arc(x, y, .8 + seeded(i * 2.2) * 1.5, 0, TAU); ctx.fill();
415:     }
416:     ctx.restore();
417:   }
