419:   // ---------- room shell ----------
420:   floorPoly(p, z = 0) {
421:     return [this.P(-.45, -.45, z), this.P(p.w + .45, -.45, z), this.P(p.w + .45, p.d + .45, z), this.P(-.45, p.d + .45, z)];
422:   }
423:   polyPath(points) {
424:     const ctx = this.ctx;
425:     ctx.beginPath();
426:     points.forEach((pt, i) => i ? ctx.lineTo(pt[0], pt[1]) : ctx.moveTo(pt[0], pt[1]));
427:     ctx.closePath();
428:   }
429:   fillPoly(points, fill, stroke = null, lw = 1) {
430:     const ctx = this.ctx;
431:     this.polyPath(points); ctx.fillStyle = fill; ctx.fill();
432:     if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
433:   }
