435:   drawRoomBase(p) {
436:     const ctx = this.ctx;
437:     const pal = p.palette;
438:     // soft ground shadow
439:     const [sx, sy] = this.P(p.w / 2, p.d / 2);
440:     ctx.save();
441:     const sg = ctx.createRadialGradient(sx, sy + 30, 20, sx, sy + 30, (p.w + p.d) * TW * .36);
442:     sg.addColorStop(0, 'rgba(0,0,0,.55)'); sg.addColorStop(.7, 'rgba(0,0,0,.22)'); sg.addColorStop(1, 'rgba(0,0,0,0)');
443:     ctx.fillStyle = sg;
444:     ctx.beginPath(); ctx.ellipse(sx, sy + 38, (p.w + p.d) * TW * .34, (p.w + p.d) * TH * .52, 0, 0, TAU); ctx.fill();
445:     ctx.restore();
446: 
447:     // extruded platform
448:     const depth = 22;
449:     const top = this.floorPoly(p, 0);
450:     const frontR = [this.P(p.w + .45, -.45, 0), this.P(p.w + .45, p.d + .45, 0)];
451:     const frontL = [this.P(-.45, p.d + .45, 0), this.P(-.45, -.45, 0)];
452:     // right side (between corner right and bottom)
453:     const rightSide = [this.P(p.w + .45, -.45, 0), this.P(p.w + .45, p.d + .45, 0), this.P(p.w + .45, p.d + .45, -depth), this.P(p.w + .45, -.45, -depth)];
454:     const leftSide = [this.P(p.w + .45, p.d + .45, 0), this.P(-.45, p.d + .45, 0), this.P(-.45, p.d + .45, -depth), this.P(p.w + .45, p.d + .45, -depth)];
455:     const backL = [this.P(-.45, p.d + .45, 0), this.P(-.45, -.45, 0), this.P(-.45, -.45, -depth), this.P(-.45, p.d + .45, -depth)];
456:     this.fillPoly(rightSide, 'rgba(5,9,8,.75)');
457:     this.fillPoly(leftSide, 'rgba(8,13,11,.85)');
458:     this.fillPoly(backL, 'rgba(5,8,7,.6)');
459:     // rim
460:     this.polyPath(top); ctx.strokeStyle = rgba(pal.accent, .28); ctx.lineWidth = 2; ctx.stroke();
461:     this.polyPath(top); ctx.strokeStyle = 'rgba(255,255,255,.05)'; ctx.lineWidth = 5; ctx.stroke();
462:     // stairs / edge blocks maybe
463:     ctx.fillStyle = 'rgba(0,0,0,.2)';
464:     this.fillPoly([this.P(p.w + .45, p.d * .45, 0), this.P(p.w + .45, p.d * .55, 0), this.P(p.w + .45, p.d * .55, -depth), this.P(p.w + .45, p.d * .45, -depth)], 'rgba(0,0,0,.25)');
465:   }
