467:   drawFloor(p) {
468:     const ctx = this.ctx;
469:     const pal = p.palette;
470:     const floor = [this.P(0, 0), this.P(p.w, 0), this.P(p.w, p.d), this.P(0, p.d)];
471:     ctx.save();
472:     this.polyPath(floor); ctx.clip();
473:     ctx.fillStyle = pal.floorA; ctx.fillRect(-2000, -2000, 4000, 4000);
474:     for (let x = 0; x < p.w; x++) {
475:       for (let y = 0; y < p.d; y++) {
476:         const even = (x + y) % 2 === 0;
477:         let c = even ? pal.floorA : pal.floorB;
478:         const v = seeded(x * 13.7 + y * 4.3);
479:         if (p.id === 'apartment') c = shade(c, (v - .5) * 12);
480:         this.fillPoly([this.P(x, y), this.P(x + 1, y), this.P(x + 1, y + 1), this.P(x, y + 1)], c);
481:         // grout / plank seams
482:         ctx.strokeStyle = p.id === 'apartment' ? 'rgba(30,20,12,.16)' : 'rgba(0,0,0,.13)';
483:         ctx.lineWidth = .7;
484:         ctx.beginPath(); ctx.moveTo(...this.P(x, y + .5)); ctx.lineTo(...this.P(x + 1, y + .5)); ctx.stroke();
485:         if (p.id === 'apartment') {
486:           ctx.beginPath(); ctx.moveTo(...this.P(x + .5, y)); ctx.lineTo(...this.P(x + .5, y + 1)); ctx.stroke();
487:         }
488:         if (p.id === 'lab' || p.id === 'empire') {
489:           ctx.strokeStyle = p.id === 'lab' ? 'rgba(120,220,255,.06)' : 'rgba(255,230,190,.055)';
490:           this.polyPath([this.P(x, y), this.P(x + 1, y), this.P(x + 1, y + 1), this.P(x, y + 1)]);
491:           ctx.stroke();
492:         }
493:       }
494:     }
495:     // stains and wear
496:     for (let i = 0; i < 14; i++) {
497:       const x = seeded(i * 3.3) * p.w, y = seeded(i * 6.1) * p.d;
498:       const r = 8 + seeded(i * 2.2) * 30;
499:       const [sx, sy] = this.P(x, y);
500:       const g = ctx.createRadialGradient(sx, sy, 0, sx, sy, r);
501:       g.addColorStop(0, p.id === 'garage' || p.id === 'warehouse' ? 'rgba(20,18,15,.15)' : 'rgba(0,0,0,.08)');
502:       g.addColorStop(1, 'rgba(0,0,0,0)');
503:       ctx.fillStyle = g; ctx.beginPath(); ctx.ellipse(sx, sy, r, r * .5, 0, 0, TAU); ctx.fill();
504:     }
505:     if (p.id === 'empire') {
506:       ctx.strokeStyle = 'rgba(255,240,210,.07)'; ctx.lineWidth = .8;
507:       for (let i = 0; i < 8; i++) {
508:         ctx.beginPath();
509:         const [x1, y1] = this.P(seeded(i) * p.w, 0);
510:         ctx.moveTo(x1, y1);
511:         ctx.bezierCurveTo(x1 + 80, y1 + 40, x1 + 140, y1 + 80, x1 + 240, y1 + 150);
512:         ctx.stroke();
513:       }
514:     }
515:     ctx.restore();
516:   }
