518:   drawWalls(p) {
519:     const ctx = this.ctx;
520:     const pal = p.palette;
521:     const wallL = [this.P(0, 0, 0), this.P(0, p.d, 0), this.P(0, p.d, WALL), this.P(0, 0, WALL)];
522:     const wallR = [this.P(0, 0, 0), this.P(p.w, 0, 0), this.P(p.w, 0, WALL), this.P(0, 0, WALL)];
523:     // left wall
524:     const gL = ctx.createLinearGradient(0, -WALL, 0, p.d * TH / 2);
525:     gL.addColorStop(0, shade(pal.wallL, 16)); gL.addColorStop(.45, pal.wallL); gL.addColorStop(1, shade(pal.wallL, -10));
526:     this.fillPoly(wallL, gL);
527:     // right wall
528:     const gR = ctx.createLinearGradient(0, -WALL, 0, p.w * TH / 2);
529:     gR.addColorStop(0, shade(pal.wallR, 12)); gR.addColorStop(.5, pal.wallR); gR.addColorStop(1, shade(pal.wallR, -14));
530:     this.fillPoly(wallR, gR);
531:     // subtle pattern
532:     const pat = (wallH, count, alpha) => {
533:       ctx.save();
534:       ctx.globalAlpha = alpha;
535:       for (let i = 1; i < count; i++) {
536:         const t = i / count;
537:         ctx.strokeStyle = 'rgba(255,255,255,.06)'; ctx.lineWidth = .7;
538:         ctx.beginPath();
539:         if (wallH === 'left') { ctx.moveTo(...this.P(0, t * p.d, 0)); ctx.lineTo(...this.P(0, t * p.d, WALL)); }
540:         else { ctx.moveTo(...this.P(t * p.w, 0, 0)); ctx.lineTo(...this.P(t * p.w, 0, WALL)); }
541:         ctx.stroke();
542:       }
543:       ctx.restore();
544:     };
545:     if (p.id === 'apartment') { pat('left', 9, .5); pat('right', 12, .5); }
546:     if (p.id === 'garage' || p.id === 'warehouse') {
547:       ctx.save(); ctx.strokeStyle = 'rgba(255,255,255,.035)'; ctx.lineWidth = .7;
548:       for (let z = 12; z < WALL; z += 18) {
549:         ctx.beginPath(); ctx.moveTo(...this.P(0, 0, z)); ctx.lineTo(...this.P(0, p.d, z)); ctx.stroke();
550:         ctx.beginPath(); ctx.moveTo(...this.P(0, 0, z)); ctx.lineTo(...this.P(p.w, 0, z)); ctx.stroke();
551:       }
552:       ctx.restore();
553:     }
554:     // skirting
555:     ctx.strokeStyle = rgba(pal.trim, .75); ctx.lineWidth = 3;
556:     ctx.beginPath(); ctx.moveTo(...this.P(0, p.d, 0)); ctx.lineTo(...this.P(0, 0, 0)); ctx.lineTo(...this.P(p.w, 0, 0)); ctx.stroke();
557:     ctx.strokeStyle = 'rgba(255,255,255,.08)'; ctx.lineWidth = 1;
558:     ctx.beginPath(); ctx.moveTo(...this.P(0, p.d, 5)); ctx.lineTo(...this.P(0, 0, 5)); ctx.lineTo(...this.P(p.w, 0, 5)); ctx.stroke();
559:     // top cap
560:     ctx.strokeStyle = rgba(pal.trim, .28); ctx.lineWidth = 2;
561:     ctx.beginPath(); ctx.moveTo(...this.P(0, p.d, WALL)); ctx.lineTo(...this.P(0, 0, WALL)); ctx.lineTo(...this.P(p.w, 0, WALL)); ctx.stroke();
562:     // corner shadow
563:     const cg = ctx.createLinearGradient(...this.P(0, 0, WALL), ...this.P(1.2, 1.2, 0));
564:     cg.addColorStop(0, 'rgba(0,0,0,.3)'); cg.addColorStop(1, 'rgba(0,0,0,0)');
565:     ctx.fillStyle = cg;
566:     this.fillPoly([this.P(0, 0, WALL), this.P(0, 0, 0), this.P(1.2, 1.2, 0), this.P(1.2, 1.2, WALL)], cg);
567:   }
568: 
569:   withWall(wall, fn) {
570:     const ctx = this.ctx;
571:     ctx.save();
572:     // Local wall space is measured in screen pixels: x runs along the wall
573:     // (positive toward the far corner), y = -z runs up the wall. Keeping both
574:     // axes at pixel scale means fonts, line widths and small details are not
575:     // stretched by the isometric projection.
576:     const dx = TW / 2 / WALL_UNIT, dy = TH / 2 / WALL_UNIT;
577:     if (wall === 'back') ctx.transform(dx, dy, 0, 1, 0, 0);
578:     else ctx.transform(-dx, dy, 0, 1, 0, 0);
579:     fn(ctx, wall);
580:     ctx.restore();
581:   }
582: 
583:   wallRect(ctx, u1, u2, z1, z2) { ctx.beginPath(); ctx.rect(U(u1), -z2, U(u2 - u1), z2 - z1); }
584: 
585:   wallText(ctx, wall, u, z, text, font, color, align = 'left') {
586:     ctx.save();
587:     ctx.translate(U(u), -z);
588:     if (wall === 'left') ctx.scale(-1, 1);
589:     ctx.font = font; ctx.fillStyle = color; ctx.textAlign = align;
590:     ctx.fillText(text, 0, 0);
591:     ctx.restore();
592:   }
