594:   drawDecor(p) {
595:     const ctx = this.ctx;
596:     const pal = p.palette;
597:     for (const deco of p.decor || []) {
598:       this.withWall(deco.wall, (c, wall) => {
599:         if (deco.type === 'window') {
600:           const u1 = deco.u1, u2 = deco.u2, z1 = deco.z1, z2 = deco.z2;
601:           const w = u2 - u1, h = z2 - z1;
602:           c.fillStyle = 'rgba(0,0,0,.35)'; this.wallRect(c, u1 - .06, u2 + .06, z1 - .06, z2 + .06); c.fill();
603:           this.wallRect(c, u1, u2, z1, z2); c.save(); c.clip();
604:           const g = c.createLinearGradient(0, -z2, 0, -z1);
605:           const night = this.game.hour < 6.5 || this.game.hour > 19;
606:           g.addColorStop(0, night ? '#0a1726' : '#7fb1a5');
607:           g.addColorStop(1, night ? '#17323a' : '#c7d99b');
608:           c.fillStyle = g; c.fillRect(U(u1), -z2, U(w), h);
609:           // buildings
610:           for (let i = 0; i < 10; i++) {
611:             const bx = U(u1) + seeded(i * 2.4 + u1) * U(w);
612:             const bw = 4 + seeded(i * 5.1) * 10, bh = 8 + seeded(i * 8.3) * 30;
613:             c.fillStyle = night ? 'rgba(8,18,26,.9)' : 'rgba(50,80,72,.45)';
614:             c.fillRect(bx, -z1 - bh, bw, bh);
615:             if (night) {
616:               c.fillStyle = 'rgba(255,205,120,.5)';
617:               for (let wy = -z1 - bh + 3; wy < -z1 - 2; wy += 5) for (let wx = bx + 1.5; wx < bx + bw - 1; wx += 4) if (seeded(wx + wy) > .55) c.fillRect(wx, wy, 1.2, 1.8);
618:             }
619:           }
620:           if (night) { c.fillStyle = 'rgba(245,245,215,.9)'; c.beginPath(); c.arc(U(u1) + U(w) * .72, -z2 + 18, 5, 0, TAU); c.fill(); }
621:           c.restore();
622:           // frame
623:           c.strokeStyle = shade(pal.trim, 15); c.lineWidth = 2.2;
624:           this.wallRect(c, u1, u2, z1, z2); c.stroke();
625:           c.strokeStyle = 'rgba(255,255,255,.15)'; c.lineWidth = .7;
626:           this.wallRect(c, u1 + .12, u2 - .12, z1 + .12, z2 - .12); c.stroke();
627:           // sill
628:           c.fillStyle = shade(pal.trim, -5); c.fillRect(U(u1) - 3, -z1, U(w) + 6, 2.4);
629:         } else if (deco.type === 'poster') {
630:           const w = deco.u2 - deco.u1, h = deco.z2 - deco.z1;
631:           c.fillStyle = 'rgba(0,0,0,.3)';
632:           c.fillRect(U(deco.u1) + 2, -deco.z2 + 2, U(w), h);
633:           c.fillStyle = '#17201a'; c.fillRect(U(deco.u1) - 2, -deco.z2 - 2, U(w) + 4, h + 4);
634:           const g = c.createLinearGradient(U(deco.u1), -deco.z2, U(deco.u2), -deco.z2);
635:           g.addColorStop(0, '#263b2c'); g.addColorStop(1, '#17251d');
636:           c.fillStyle = g; c.fillRect(U(deco.u1), -deco.z2, U(w), h);
637:           c.strokeStyle = rgba(deco.color, .6); c.lineWidth = .8;
638:           c.strokeRect(U(deco.u1) + .8, -deco.z2 + .8, U(w) - 1.6, h - 1.6);
639:           const tx = wall === 'left' ? deco.u2 - .55 : deco.u1 + .55;
640:           this.wallText(c, wall, tx, deco.z2 - 12, deco.title || '', '900 12px "Arial Black", Impact, sans-serif', deco.color);
641:           this.wallText(c, wall, tx, deco.z2 - 21, deco.sub || '', '700 6px system-ui', 'rgba(255,255,255,.55)');
642:           // leaf doodle
643:           c.strokeStyle = rgba(deco.color, .35); c.lineWidth = 1;
644:           for (let i = 0; i < 3; i++) { c.beginPath(); c.ellipse(U(deco.u1) + 9 + i * 5, -deco.z1 + 10 + i * 1.4, 4, 2, -.6 + i * .3, 0, TAU); c.stroke(); }
645:         } else if (deco.type === 'shelf') {
646:           const w = U(deco.u2 - deco.u1);
