export class Game {
  constructor() {
    this.listeners = new Map();
    this.runtime = { customers: [], spawnTimer: 5, staffTimers: { bea: 0, tito: 0, mara: 0, eli: 0 }, eventTimer: 95, autosave: 0, launderAcc: 0, uiPaused: false, pendingEvent: null, raidCooldown: 0, lastFrame: 0 };
    this.state = this.newState();
  }

  // ---------- setup & persistence ----------
  newState() {
    const properties = {};
    for (const p of PROPERTY_LIST) {
      properties[p.id] = {
        owned: p.id === 'apartment',
        slots: p.slots.map(() => null),
        upgrades: { lights: 0, vent: 0, irrigation: 0, security: 0, counter: 0 }
      };
    }
    return {
      version: 2, clock: 0, lastSave: Date.now(),
